<script setup lang="ts">
/**
 * Free-text tags (`design/components/tag-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tag-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  shallowRef,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import { agentMember, composingKey, holdFieldEscape, lineStartKey } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/tag-input.module.css'
import TagInputChip from './TagInputChip.vue'

export type TagInputCountLabel = (tags: { count: number; max?: number; atMax: boolean }) => string

export interface TagInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * The count sentence in the host's words, part of the field's description, the localization
   * seam; the default is `{count} added`, or `Maximum of {max} added` at the maximum.
   */
  countLabel?: TagInputCountLabel
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * At the maximum the field is read-only, not removed and not disabled. A full field is still
   * what FormField's label points at, and keyboard users can still reach it. It blocks typing,
   * not access.
   */
  max?: number
  /**
   * Serialises comma-joined into a hidden input, for a native form post.
   */
  name?: string
  /**
   * Shown only while empty. The chips are the value, and a placeholder beside them is clutter.
   */
  placeholder?: string
  /**
   * The accessible name of a chip's remove button. It is a function because the tag is data and
   * the text around it comes from the app's message catalog. Defaults to `Remove {tag}`.
   */
  removeLabel?: (tag: string) => string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalize or reject: return the tag as it should be stored, or `null` to reject it. A
   * rejection flashes the container and shows no message. Persistent written errors come from
   * FormField.
   */
  validate?: (raw: string) => string | null
  value?: string[]
}

defineOptions({ name: 'TagInput', inheritAttrs: false, controlKind: 'field' })

const props = withDefaults(defineProps<TagInputProps>(), {
  ariaRequired: undefined,
  countLabel: ({ count, max, atMax }: Parameters<TagInputCountLabel>[0]) =>
    atMax ? `Maximum of ${max} added` : `${count} added`,
  disabled: false,
  invalid: false,
  removeLabel: (tag: string) => `Remove ${tag}`,
  size: 'md',
  validate: (raw: string) => (raw.trim() === '' ? null : raw.trim()),
})
const emit = defineEmits<{ blur: [event: FocusEvent]; change: [values: string[]] }>()
const uid = useId()
const uncontrolled = ref(props.defaultValue ?? [])
const draft = ref('')
const flashing = ref(null as string | null)
const refused = ref(false)
const announcement = ref('')
const settled = ref(false)
const chipList = useTemplateRef<HTMLElement>('chipList')
const field = useTemplateRef<HTMLElement>('field')
const values = computed(() => props.value ?? uncontrolled.value)
const atMax = computed(() => props.max !== undefined && values.value.length >= props.max)
const countId = computed(() => `${props.id ?? uid}-count`)
const commit = computed(() => (next: string[]) => {
  uncontrolled.value = next
  emit('change', next)
})
const add = computed(() => (raws: string[]) => {
  const next = [...values.value]
  let refusal = false
  let duplicate: string | null = null
  for (const raw of raws) {
    if (props.max !== undefined && next.length >= props.max) break
    const tag = props.validate(raw)
    if (tag === null) {
      refusal = true
      continue
    }
    if (next.includes(tag)) {
      duplicate = tag
      continue
    }
    next.push(tag)
  }
  refused.value = refusal
  flashing.value = duplicate
  if (next.length !== values.value.length) commit.value(next)
})
const removeButton = computed(
  () => (at: number) =>
    chipList.value?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[at] ??
    null,
)
const remove = computed(() => (tag: string) => {
  const before = values.value
  const at = before.indexOf(tag)
  const target = at === -1 || at + 1 >= before.length ? null : removeButton.value(at + 1)
  commit.value(before.filter((other) => other !== tag))
  announcement.value = `${tag} removed, ${before.length - 1} remain`
  if (target) target.focus()
  else field.value?.focus()
})
const receive = computed(() => (event: Event) => {
  draft.value = (event.target as HTMLInputElement).value
})
const clearable = computed(() => draft.value !== '')
const fieldKeyDown = computed(() => (event: KeyboardEvent) => {
  if (composingKey(event)) return
  if (event.key === 'Enter' || event.key === ',') {
    event.preventDefault()
    add.value([draft.value])
    draft.value = ''
    return
  }
  if (event.key === 'Escape' && draft.value !== '') {
    event.preventDefault()
    draft.value = ''
    return
  }
  if (event.key === 'Backspace' && draft.value === '') {
    const last = values.value[values.value.length - 1]
    if (last !== undefined) remove.value(last)
    return
  }
  // The direction is a computed style, read only for an arrow.
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return
  const input = event.target as HTMLInputElement
  if (event.key === lineStartKey(chipList.value ?? input) && input.selectionStart === 0) {
    removeButton.value(values.value.length - 1)?.focus()
  }
})
const chipKeyDown = computed(() => (event: KeyboardEvent, tag: string) => {
  const at = values.value.indexOf(tag)
  if (at === -1) return
  if (event.key === 'Backspace' || event.key === 'Delete') {
    event.preventDefault()
    remove.value(tag)
    return
  }
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault()
    const step = event.key === lineStartKey(chipList.value ?? (event.target as Element)) ? -1 : 1
    if (at + step === values.value.length) field.value?.focus()
    else if (at + step >= 0) removeButton.value(at + step)?.focus()
  }
})
const receivePaste = computed(() => (event: ClipboardEvent) => {
  const pasted = event.clipboardData?.getData('text') ?? ''
  if (!/[\n,]+/.test(pasted)) return
  event.preventDefault()
  add.value(pasted.split(/[\n,]+/))
  draft.value = ''
})
const pressContainer = computed(() => (event: MouseEvent) => {
  if ((event.target as HTMLElement).closest('button, input')) return
  event.preventDefault()
  field.value?.focus()
})
const leave = computed(() => (event: FocusEvent) => {
  if ((event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) return
  emit('blur', event)
})
const chipsOf = () => values.value
const chipsKey = (tag: string) => tag
const chipsLeaving = shallowRef<
  { key: string; item: ReturnType<typeof chipsOf>[number]; at: number }[]
>([])
watch(
  chipsOf,
  (now, before) => {
    const kept = new Set(now.map(chipsKey))
    const leaving = chipsLeaving.value.filter((entry) => !kept.has(entry.key))
    before.forEach((item, at) => {
      const key = chipsKey(item)
      if (!kept.has(key) && !leaving.some((entry) => entry.key === key))
        leaving.push({ key, item, at })
    })
    chipsLeaving.value = leaving
  },
  { flush: 'sync' },
)
const chips = computed(() => {
  const entries = chipsOf().map((item) => ({
    item,
    key: chipsKey(item),
    open: true,
    done: () => {},
  }))
  for (const entry of [...chipsLeaving.value].sort((a, b) => a.at - b.at))
    entries.splice(Math.min(entry.at, entries.length), 0, {
      item: entry.item,
      key: entry.key,
      open: false,
      done: () => {
        chipsLeaving.value = chipsLeaving.value.filter((other) => other.key !== entry.key)
      },
    })
  return entries
})
const effect1 = () => {
  settled.value = true
}
onMounted(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = clearable.value && field.value ? holdFieldEscape(field.value) : () => {}
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
watch(() => clearable.value, effect2, { flush: 'post' })
onBeforeUnmount(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'TagInput',
    element: () => field.value,
    state: () => ({ value: values.value, disabled: props.disabled, invalid: props.invalid }),
    actions: {
      add: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (/[\n,]/.test(value)) {
              throw new Error('A tag holds no comma or line break: add each tag on its own.')
            }
            if (atMax.value) throw new Error(`The field holds its maximum of ${props.max} tags.`)
            const tag = props.validate(value)
            if (tag === null) throw new Error(`The field refuses "${value}" as a tag.`)
            if (values.value.includes(tag)) throw new Error(`The field already holds "${tag}".`)
            add.value([value])
          })(),
      },
      clear: () =>
        (() => {
          if (values.value.length > 0) commit.value([])
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    :class="styles.container"
    :data-size="size"
    :data-state="atMax ? 'at-max' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-refused="refused ? '' : undefined"
    data-member="tag-input"
    @mousedown="pressContainer($event)"
    @focusout="leave($event)"
    @animationend="((refused = false), (flashing = null))"
  >
    <!-- chips -->
    <ul ref="chipList" :class="styles.chips">
      <template v-for="chip in chips" :key="chip.key">
        <TagInputChip
          :tag="chip.item"
          :open="chip.open"
          :appear="settled"
          :flash="flashing === chip.item"
          :disabled="disabled"
          :removeLabel="removeLabel(chip.item)"
          @remove="remove(chip.item)"
          @keyDown="chipKeyDown($event, chip.item)"
          @done="chip.done()"
        />
      </template>
    </ul>
    <!-- field -->
    <input
      ref="field"
      :class="styles.input"
      type="text"
      :value="draft"
      :placeholder="values.length === 0 ? placeholder : undefined"
      :readonly="atMax"
      :disabled="disabled"
      :id="id"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="[ariaDescribedby, countId].filter(Boolean).join(' ')"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
      @input="receive($event)"
      @keydown="fieldKeyDown($event)"
      @paste="receivePaste($event)"
    />
    <!-- count -->
    <span :class="styles.reader" :id="countId">
      {{ countLabel({ count: values.length, max, atMax }) }}
    </span>
    <!-- announcer -->
    <span :class="styles.reader" aria-live="polite">
      {{ announcement }}
    </span>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="values.join(',')"
      :disabled="disabled"
    />
  </div>
</template>
